#!/usr/bin/env node
// Generates the per-platform RSVP/ChunkShaper constant modules from the single
// source of truth Tools/rsvp-spec.json. Run after editing the spec:
//
//   node Tools/gen-rsvp-spec.mjs
//
// CI re-runs this and fails if the committed generated files differ
// (scripts/verify-rsvp-spec.sh), so the three platform copies can never
// silently drift again.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const spec = JSON.parse(readFileSync(join(root, 'Tools', 'rsvp-spec.json'), 'utf8'));

const HEADER = (lang) =>
  `// Generated by Tools/gen-rsvp-spec.mjs from Tools/rsvp-spec.json. DO NOT EDIT.\n` +
  `// Edit the spec and re-run the generator; CI drift-gates this file.\n`;

const hex = (n) => '0x' + n.toString(16).toUpperCase();

// ---- Swift -----------------------------------------------------------------

function swiftChar(s) {
  const esc = s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return `"${esc}"`;
}
const swiftCharSet = (arr) => `[${arr.map(swiftChar).join(', ')}]`;
const swiftRanges = (arr) => `[${arr.map(([a, b]) => `${hex(a)}...${hex(b)}`).join(', ')}]`;

function emitSwift() {
  const c = spec.chunkShaper;
  return (
    HEADER('swift') +
    `import Foundation\n\n` +
    `enum RSVPSpec {\n` +
    `    static let version: Int = ${spec.version}\n\n` +
    `    enum WPM {\n` +
    `        static let \`default\`: Double = ${spec.wpm.default}\n` +
    `        static let minimumSafe: Double = ${spec.wpm.minimumSafe}\n` +
    `        static let maximum: Double = ${spec.wpm.maximum}\n` +
    `        static let step: Double = ${spec.wpm.step}\n` +
    `        static let minimumUserLatin: Double = ${spec.wpm.minimumUser.latin}\n` +
    `        static let minimumUserCJK: Double = ${spec.wpm.minimumUser.cjk}\n` +
    `    }\n\n` +
    `    enum Duration {\n` +
    `        static let baseMillisPerMinute: Double = ${spec.duration.baseMillisPerMinute}\n` +
    `        static let cjkMultiplier: Double = ${spec.duration.cjkMultiplier}\n` +
    `        static let lengthThreshold: Int = ${spec.duration.lengthThreshold}\n` +
    `        static let lengthPerCharIncrement: Double = ${spec.duration.lengthPerCharIncrement}\n` +
    `        static let lengthMaxIncrement: Double = ${spec.duration.lengthMaxIncrement}\n` +
    `        static let pauseMultiplier: Double = ${spec.duration.pauseMultiplier}\n` +
    `    }\n\n` +
    `    static let cjkRanges: [ClosedRange<UInt32>] = ${swiftRanges(spec.ranges.cjk)}\n` +
    `    static let hanRanges: [ClosedRange<UInt32>] = ${swiftRanges(spec.ranges.han)}\n` +
    `    static let cjkPunctuationRanges: [ClosedRange<UInt32>] = ${swiftRanges(spec.ranges.cjkPunctuation)}\n\n` +
    `    static let asciiPause: Set<Character> = ${swiftCharSet(spec.punctuation.asciiPause)}\n` +
    `    static let latinSentenceEnd: Set<Character> = ${swiftCharSet(spec.punctuation.latinSentenceEnd)}\n` +
    `    static let latinTrailingClosers: Set<Character> = ${swiftCharSet(spec.punctuation.latinTrailingClosers)}\n\n` +
    `    enum ChunkShaper {\n` +
    `        static let maxMergedCJK: Int = ${c.maxMergedCJK}\n` +
    `        static let possessiveDe: Character = ${swiftChar(c.possessiveDe)}\n` +
    `        static let measureWords: Set<String> = ${swiftCharSet(c.measureWords)}\n` +
    `        static let prepositionsForCompound: Set<Character> = ${swiftCharSet(c.prepositionsForCompound)}\n` +
    `        static let particlesBackward: Set<Character> = ${swiftCharSet(c.particlesBackward)}\n` +
    `        static let particlesForward: Set<Character> = ${swiftCharSet(c.particlesForward)}\n` +
    `        static let pronouns: Set<Character> = ${swiftCharSet(c.pronouns)}\n` +
    `        static let peelForwardVerbs: Set<Character> = ${swiftCharSet(c.peelForwardVerbs)}\n` +
    `        static let hardClauseEndings: Set<Character> = ${swiftCharSet(c.hardClauseEndings)}\n` +
    `    }\n` +
    `}\n`
  );
}

// ---- TypeScript ------------------------------------------------------------

const tsStr = (s) => JSON.stringify(s);
const tsStrArr = (arr) => `[${arr.map(tsStr).join(', ')}]`;
const tsRanges = (arr) => `[${arr.map(([a, b]) => `[${hex(a)}, ${hex(b)}]`).join(', ')}]`;

function emitTs() {
  const c = spec.chunkShaper;
  return (
    HEADER('ts') +
    `\n/* eslint-disable */\n` +
    `export const RSVP_SPEC = {\n` +
    `  version: ${spec.version},\n` +
    `  wpm: {\n` +
    `    default: ${spec.wpm.default},\n` +
    `    minimumSafe: ${spec.wpm.minimumSafe},\n` +
    `    maximum: ${spec.wpm.maximum},\n` +
    `    step: ${spec.wpm.step},\n` +
    `    minimumUser: { latin: ${spec.wpm.minimumUser.latin}, cjk: ${spec.wpm.minimumUser.cjk} },\n` +
    `  },\n` +
    `  duration: {\n` +
    `    baseMillisPerMinute: ${spec.duration.baseMillisPerMinute},\n` +
    `    cjkMultiplier: ${spec.duration.cjkMultiplier},\n` +
    `    lengthThreshold: ${spec.duration.lengthThreshold},\n` +
    `    lengthPerCharIncrement: ${spec.duration.lengthPerCharIncrement},\n` +
    `    lengthMaxIncrement: ${spec.duration.lengthMaxIncrement},\n` +
    `    pauseMultiplier: ${spec.duration.pauseMultiplier},\n` +
    `  },\n` +
    `  ranges: {\n` +
    `    cjk: ${tsRanges(spec.ranges.cjk)},\n` +
    `    han: ${tsRanges(spec.ranges.han)},\n` +
    `    cjkPunctuation: ${tsRanges(spec.ranges.cjkPunctuation)},\n` +
    `  },\n` +
    `  punctuation: {\n` +
    `    asciiPause: ${tsStrArr(spec.punctuation.asciiPause)},\n` +
    `    latinSentenceEnd: ${tsStrArr(spec.punctuation.latinSentenceEnd)},\n` +
    `    latinTrailingClosers: ${tsStrArr(spec.punctuation.latinTrailingClosers)},\n` +
    `  },\n` +
    `  chunkShaper: {\n` +
    `    maxMergedCJK: ${c.maxMergedCJK},\n` +
    `    possessiveDe: ${tsStr(c.possessiveDe)},\n` +
    `    measureWords: ${tsStrArr(c.measureWords)},\n` +
    `    prepositionsForCompound: ${tsStrArr(c.prepositionsForCompound)},\n` +
    `    particlesBackward: ${tsStrArr(c.particlesBackward)},\n` +
    `    particlesForward: ${tsStrArr(c.particlesForward)},\n` +
    `    pronouns: ${tsStrArr(c.pronouns)},\n` +
    `    peelForwardVerbs: ${tsStrArr(c.peelForwardVerbs)},\n` +
    `    hardClauseEndings: ${tsStrArr(c.hardClauseEndings)},\n` +
    `  },\n` +
    `} as const;\n`
  );
}

// ---- Kotlin ----------------------------------------------------------------

function ktChar(s) {
  const esc = s.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return `'${esc}'`;
}
function ktStr(s) {
  const esc = s.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\$/g, '\\$');
  return `"${esc}"`;
}
const ktCharSet = (arr) => `setOf(${arr.map(ktChar).join(', ')})`;
const ktStrSet = (arr) => `setOf(${arr.map(ktStr).join(', ')})`;
const ktRanges = (arr) => `listOf(${arr.map(([a, b]) => `${hex(a)}..${hex(b)}`).join(', ')})`;

function emitKotlin(pkg) {
  const c = spec.chunkShaper;
  return (
    HEADER('kotlin') +
    `\npackage ${pkg}\n\n` +
    `object RsvpSpec {\n` +
    `    const val VERSION = ${spec.version}\n\n` +
    `    object Wpm {\n` +
    `        const val DEFAULT = ${spec.wpm.default}.0\n` +
    `        const val MINIMUM_SAFE = ${spec.wpm.minimumSafe}.0\n` +
    `        const val MAXIMUM = ${spec.wpm.maximum}.0\n` +
    `        const val STEP = ${spec.wpm.step}.0\n` +
    `        const val MINIMUM_USER_LATIN = ${spec.wpm.minimumUser.latin}.0\n` +
    `        const val MINIMUM_USER_CJK = ${spec.wpm.minimumUser.cjk}.0\n` +
    `    }\n\n` +
    `    object Duration {\n` +
    `        const val BASE_MILLIS_PER_MINUTE = ${spec.duration.baseMillisPerMinute}.0\n` +
    `        const val CJK_MULTIPLIER = ${spec.duration.cjkMultiplier}\n` +
    `        const val LENGTH_THRESHOLD = ${spec.duration.lengthThreshold}\n` +
    `        const val LENGTH_PER_CHAR_INCREMENT = ${spec.duration.lengthPerCharIncrement}\n` +
    `        const val LENGTH_MAX_INCREMENT = ${spec.duration.lengthMaxIncrement}\n` +
    `        const val PAUSE_MULTIPLIER = ${spec.duration.pauseMultiplier}\n` +
    `    }\n\n` +
    `    val cjkRanges = ${ktRanges(spec.ranges.cjk)}\n` +
    `    val hanRanges = ${ktRanges(spec.ranges.han)}\n` +
    `    val cjkPunctuationRanges = ${ktRanges(spec.ranges.cjkPunctuation)}\n\n` +
    `    val asciiPause = ${ktCharSet(spec.punctuation.asciiPause)}\n` +
    `    val latinSentenceEnd = ${ktCharSet(spec.punctuation.latinSentenceEnd)}\n` +
    `    val latinTrailingClosers = ${ktCharSet(spec.punctuation.latinTrailingClosers)}\n\n` +
    `    object ChunkShaper {\n` +
    `        const val MAX_MERGED_CJK = ${c.maxMergedCJK}\n` +
    `        const val POSSESSIVE_DE = ${ktChar(c.possessiveDe)}\n` +
    `        val measureWords = ${ktStrSet(c.measureWords)}\n` +
    `        val prepositionsForCompound = ${ktCharSet(c.prepositionsForCompound)}\n` +
    `        val particlesBackward = ${ktCharSet(c.particlesBackward)}\n` +
    `        val particlesForward = ${ktCharSet(c.particlesForward)}\n` +
    `        val pronouns = ${ktCharSet(c.pronouns)}\n` +
    `        val peelForwardVerbs = ${ktCharSet(c.peelForwardVerbs)}\n` +
    `        val hardClauseEndings = ${ktCharSet(c.hardClauseEndings)}\n` +
    `    }\n` +
    `}\n`
  );
}

// ---- Write -----------------------------------------------------------------

const KT_PKG = 'com.shhtheonlyperson.fastread.spike.core';
const targets = [
  ['Sources/FastReadCore/RSVPSpec.generated.swift', emitSwift()],
  ['chrome-ext/src/lib/rsvpSpec.generated.ts', emitTs()],
  [
    'android-spike/app/src/main/java/com/shhtheonlyperson/fastread/spike/core/RsvpSpec.generated.kt',
    emitKotlin(KT_PKG),
  ],
];

for (const [rel, content] of targets) {
  writeFileSync(join(root, rel), content);
  console.log(`wrote ${rel}`);
}
